import json,os
R=os.path.dirname(os.path.abspath(__file__));sp=json.load(open(R+'/out/rc1.spec.json'))
PUR=["HOOK: a smile + a zombie walking right behind her; nobody reacts → 'calm is invisible' shown before it is told","Teddy is the audience proxy: he thinks it's a costume (plants: kid doesn't know to be scared)","BOMB UNDER THE TABLE: audience sees 3 zombies drift toward Gus who has his back to them; PA line planted","Gus characterised: phone, relaxed, jumpy-in-waiting","RULE OF THREE #1: Carrot creeps up behind Gus (audience sees)","#1 payoff: Gus turns — nothing","RULE OF THREE #2: Carrot closer","#2 payoff: Gus turns — nothing","#3: Carrot is RIGHT THERE; silence (gate) before the scream","Scream = fear spike (the inciting event)","The dead respond to fear: charge (run = fear)","Mimi states the rule early, then Gus runs into her","Mimi talks him down (profile two-shot): breathe in 4, smile","The dead pass inches from them; total silence, heartbeat ticks","Dr. Vance supplies the theory in one line","Rules card (≤15% of runtime) voiced as store-policy by Mimi","Proof: Teddy strolls through the dead, calm because he does not know","Emotional beat: Gus asks, Mimi's smile is her armour","COMPLICATION: Rosa + crying baby = maximum fear","Every head turns (silence → stinger)","PAYOFF of the PA line: Gus (the fearful one) says it","LOOP/CLIFFHANGER: hook frame again, zombie now standing behind her"]
out=["# REMAIN CALM · Part 1 — THE DEAD SMELL FEAR","","**Logline:** A cashier whose smile never breaks must teach a jumpy security guard to stay calm before the dead — who can smell fear — find him.","","**What it is really about:** calm is contagious; fear spreads faster than the dead.","","**Emotional arc:** deadpan normality → creeping dread → panic (Gus) → learning calm → complication (Rosa) → cliff.","","**Director's rules:** no narrator · ≤3.5 s average shot · every shot has a purpose (below) · silence before reveals (3 gates) · rule of three (Carrot) · plant & payoff (PA line) · loop ending · hero frames: front for emotion, profile for conversation, back for dread.","","## Shot list",f"Runtime {sp['dur']:.1f}s · {len(sp['shots'])} shots · avg {sp['dur']/len(sp['shots']):.2f}s","","| # | time | place | lines | purpose |","|---|---|---|---|---|"]
for i,s in enumerate(sp['shots']):
    ln=' / '.join(f"{L['name'] or L['who']}: {L['en']}" for L in s['lines']) or ('(card)' if s.get('card') else '—')
    out.append(f"| {i+1} | {s['t0']:.1f}–{s['t1']:.1f} | {s.get('place') or 'CARD'} | {ln} | {PUR[i]} |")
out+=["","## Continuity sheet","- Time on strip: 2:47 AM (checkout) never changes; place strip follows location.","- Zombie count: z1 at till (shots 1,22) · z2,z3,z4 in aisle 9 (3,11,14,17,20) — all four seen together only in 3 & 20.","- Gus: phone in hand shots 4 only; cap + badge always; Mimi: till tag; Teddy: red tee, can in shot 17.","- Light: flicker on light #3 continuous; grade: calm → alarm (scream) → cold (breathing) → dead (zombies pass) → warm (Mimi's smile) → alarm (Rosa) → dead (turn) → cold → calm.","","## Sound plan","- Bed: fluorescent hum all film; calm music-box motif on the hook (detuned when danger is near).","- Silence gates (3): before the scream (shot 9), while the dead pass (14), before the heads turn (20). Stingers right after 9→10 and 20.","- PA = intercom filter; baby cry is the only sustained loud sound in the film.","","## QC (self-check before showing)",""]
QC=["Logline + theme clear","Every shot has a purpose","Hook in 3 s (smile + zombie behind her)","One idea, one place (Freshway)","Plant→payoff (PA line, Teddy's 'costume')","Rule of three (Carrot)","Silence before reveals (3 gates)","No narrator","Avg shot ≤3.5 s","Cards ≤15% of runtime (1 rules card)","Characters facing correct way / not black / not on shelves","Captions fit","Loop ending"]
out+=[f"- [x] {q}" for q in QC]
open(R+'/episodes/RC1_DIRECTOR.md','w').write('\n'.join(out)+'\n');print('ok')
